N;s:10:\"badgeColor\";N;s:8:\"isActive\";b:0;s:16:\"isAncestorActive\";b:0;s:5:\"depth\";i:0;s:9:\"sortOrder\";i:1;s:8:\"children\";a:0:{}s:6:\"locale\";N;s:11:\"openInModal\";b:0;}i:2;O:34:\"App\\Navigation\\DTOs\\NavigationNode\":20:{s:2:\"id\";s:36:\"019f75b1-e16f-71c1-96c1-b4f44ead1001\";s:12:\"navigationId\";s:36:\"019f75ac-3cbf-72cf-9733-4ec32d1ac225\";s:5:\"label\";s:10:\"Contact Us\";s:4:\"link\";O:32:\"App\\Navigation\\DTOs\\ResolvedLink\":4:{s:3:\"url\";s:32:\"http://127.0.0.1:8000/contact-us\";s:6:\"target\";s:5:\"_self\";s:3:\"rel\";N;s:10:\"attributes\";a:0:{}}s:10:\"visibility\";r:18;s:13:\"publishWindow\";O:33:\"App\\Navigation\\DTOs\\PublishWindow\":2:{s:8:\"startsAt\";N;s:6:\"endsAt\";N;}s:15:\"requiredRoleIds\";a:0:{}s:21:\"requiredPermissionIds\";a:0:{}s:4:\"icon\";N;s:8:\"cssClass\";N;s:5:\"cssId\";N;s:9:\"badgeText\";N;s:10:\"badgeColor\";N;s:8:\"isActive\";b:0;s:16:\"isAncestorActive\";b:0;s:5:\"depth\";i:0;s:9:\"sortOrder\";i:2;s:8:\"children\";a:0:{}s:6:\"locale\";N;s:11:\"openInModal\";b:0;}}}',	1784399546),
