INSERT INTO `faq_categories` (`id`, `name`, `description`, `icon`, `display_order`, `is_active`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
('019f23db-e2c5-7249-83db-681b1e535bfa',	'Instructor',	NULL,	NULL,	0,	1,	1,	1,	'2026-07-02 11:54:00',	'2026-07-18 09:59:12',	'2026-07-18 09:59:12'),
('019f23dd-e879-7066-8c87-170645018291',	'Student',	NULL,	NULL,	0,	1,	1,	1,	'2026-07-02 11:56:13',	'2026-07-18 09:59:16',	'2026-07-18 09:59:16'),
('019f75c0-82fa-704b-b378-bbaf4e9873a5',	'Become an Instructor',	'Answers for prospective instructors exploring the application process.',	'academic-cap',	0,	1,	NULL,	NULL,	'2026-07-18 09:32:58',	'2026-07-18 09:32:58',	NULL),
('019f75c0-837f-72fe-a7c3-c27865cff88b',	'Student FAQs',	'Booking, wallet, and progress questions for students.',	'user-graduate',	1,	1,	NULL,	NULL,	'2026-07-18 09:32:58',	'2026-07-18 09:32:58',	NULL),
('019f75c0-83c5-72f2-94c9-6020dae969bd',	'Instructor FAQs',	'Teaching workflow, earnings, and availability questions for instructors.',	'chalkboard-teacher',	2,	1,	NULL,	NULL,	'2026-07-18 09:32:58',	'2026-07-18 09:32:58',	NULL);
INSERT INTO `faqs` (`id`, `faq_category_id`, `question`, `answer`, `audience`, `display_order`, `featured`, `status`, `published_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
('019f23dd-8343-71fc-a388-92f85db2d5cc',	'019f23db-e2c5-7249-83db-681b1e535bfa',	'What kind of courses do you offer?',	'<p>We offer a wide range of courses in various subjects, from business and technology to art and personal development. You can browse our extensive catalog to find a course that interests you.</p>',	'[\"student\"]',	0,	1,	'published',	'2026-07-02 17:24:30',	1,	1,	'2026-07-02 11:55:47',	'2026-07-18 10:01:05',	'2026-07-18 10:01:05'),
('019f23de-9bbe-72da-8e37-f96e8ba11495',	'019f75c0-837f-72fe-a7c3-c27865cff88b',	'Who are your instructors?',	'<p>Our instructors are industry experts and passionate educators with a wealth of knowledge and experience. You can learn more about their qualifications on their course profiles.</p>',	'[\"student\"]',	0,	1,	'published',	NULL,	1,	1,	'2026-07-02 11:56:59',	'2026-07-18 10:01:52',	NULL),
('019f75c0-832f-73f6-a70d-af02a3bd8a98',	'019f75c0-82fa-704b-b378-bbaf4e9873a5',	'Who can apply to teach?',	'University students, graduates, working professionals and experienced teachers can apply. Current school students up to and including grade 12 are not eligible to apply as instructors.',	'[\"public\"]',	0,	1,	'published',	'2026-07-18 09:33:15',	NULL,	NULL,	'2026-07-18 09:32:58',	'2026-07-18 09:33:15',	NULL),
('019f75c0-833d-7214-a2b3-72a0fb75ae70',	'019f75c0-82fa-704b-b378-bbaf4e9873a5',	'What verification documents may be required?',	'<p>Requirements are configurable and may include a government-issued ID, profile photograph, address proof, educational qualifications, professional certificates, resume, and an introduction video.</p>',	'[\"public\"]',	1,	1,	'published',	'2026-07-18 09:33:15',	NULL,	1,	'2026-07-18 09:32:58',	'2026-07-18 10:04:53',	NULL),
('019f75c0-8348-73b7-a707-86b8919b251d',	'019f75c0-82fa-704b-b378-bbaf4e9873a5',	'How long does the review take?',	'<p>Review time depends on application volume and whether the submitted information is complete. You can track your current application status from your dashboard.</p>',	'[\"public\"]',	2,	1,	'published',	'2026-07-18 09:33:16',	NULL,	1,	'2026-07-18 09:32:58',	'2026-07-18 10:05:07',	NULL),
('019f75c0-8359-730f-8508-cf43e10c4b1b',	'019f75c0-82fa-704b-b378-bbaf4e9873a5',	'How much can I earn?',	'<p>Potential earnings depend on completed and approved lessons, availability, pricing, student demand, and platform policies. The platform does not guarantee fixed income.</p>',	'[\"public\"]',	3,	1,	'published',	'2026-07-18 09:33:16',	NULL,	1,	'2026-07-18 09:32:58',	'2026-07-18 10:05:16',	NULL),
('019f75c0-836f-71e1-85a8-572409770968',	'019f75c0-82fa-704b-b378-bbaf4e9873a5',	'What happens after I submit my application?',	'Your application moves through a verification workflow. You can track its status from your dashboard and will be notified once a decision has been made.',	'[\"public\"]',	4,	0,	'published',	'2026-07-18 09:33:16',	NULL,	NULL,	'2026-07-18 09:32:58',	'2026-07-18 09:33:16',	NULL),
('019f75c0-8377-72e0-b9e2-33e5d5826659',	'019f75c0-82fa-704b-b378-bbaf4e9873a5',	'Can I reapply if my application is not approved?',	'<p>Contact support for details on reapplying after an application is not approved.</p>',	'[\"public\"]',	5,	1,	'published',	'2026-07-18 09:33:16',	NULL,	1,	'2026-07-18 09:32:58',	'2026-07-18 10:04:22',	NULL),
('019f75c0-8388-7360-ac73-e9194a19bd37',	'019f75c0-837f-72fe-a7c3-c27865cff88b',	'How do I book a lesson with an instructor?',	'Browse verified instructor profiles, choose a subject and an available time slot, and confirm your booking from the instructor\'s profile.',	'[\"student\"]',	0,	1,	'published',	'2026-07-18 09:33:16',	NULL,	NULL,	'2026-07-18 09:32:58',	'2026-07-18 09:33:16',	NULL),
('019f75c0-8394-7006-af8b-fa3e87b87b9b',	'019f75c0-837f-72fe-a7c3-c27865cff88b',	'What is a demo lesson?',	'A demo lesson is a free introductory lesson that lets you evaluate an instructor before booking paid lessons. Availability is limited according to platform rules.',	'[\"student\"]',	1,	0,	'published',	'2026-07-18 09:33:16',	NULL,	NULL,	'2026-07-18 09:32:58',	'2026-07-18 09:33:16',	NULL),
('019f75c0-839d-7171-b0a8-8d369eda8dec',	'019f75c0-837f-72fe-a7c3-c27865cff88b',	'How does my wallet work?',	'Your wallet holds a digital balance in your billing currency for lesson payments, refunds, and rewards. You can recharge it from your dashboard.',	'[\"student\"]',	2,	0,	'published',	'2026-07-18 09:33:16',	NULL,	NULL,	'2026-07-18 09:32:58',	'2026-07-18 09:33:16',	NULL),
('019f75c0-83a7-7294-bf30-4112985ef8f0',	'019f75c0-837f-72fe-a7c3-c27865cff88b',	'Can I cancel or reschedule a booked lesson?',	'Yes, from your dashboard, subject to the platform\'s cancellation and rescheduling policy.',	'[\"student\"]',	3,	0,	'published',	'2026-07-18 09:33:16',	NULL,	NULL,	'2026-07-18 09:32:58',	'2026-07-18 09:33:16',	NULL),
('019f75c0-83b0-70db-baa0-486403cc8fe3',	'019f75c0-837f-72fe-a7c3-c27865cff88b',	'How do I track my learning progress?',	'Your dashboard shows your lessons, homework, and learning plan progress in one place.',	'[\"student\"]',	4,	0,	'published',	'2026-07-18 09:33:16',	NULL,	NULL,	'2026-07-18 09:32:58',	'2026-07-18 09:33:16',	NULL),
('019f75c0-83bb-729a-8191-eee97970a9b8',	'019f75c0-837f-72fe-a7c3-c27865cff88b',	'What if I\'m not satisfied with a lesson?',	'You can leave a review and private feedback after each lesson, and contact support if you have concerns.',	'[\"student\"]',	5,	0,	'published',	'2026-07-18 09:33:16',	NULL,	NULL,	'2026-07-18 09:32:58',	'2026-07-18 09:33:16',	NULL),
('019f75c0-83d1-7226-8c83-98016000feeb',	'019f75c0-83c5-72f2-94c9-6020dae969bd',	'How do I manage my upcoming lessons?',	'Your dashboard lists upcoming and recent lessons, including options to join, review student details, and record outcomes.',	'[\"instructor\"]',	0,	1,	'published',	'2026-07-18 09:33:16',	NULL,	NULL,	'2026-07-18 09:32:58',	'2026-07-18 09:33:16',	NULL),
('019f75c0-83dc-73a7-8605-a644e2cc8c88',	'019f75c0-83c5-72f2-94c9-6020dae969bd',	'How and when do I get paid?',	'Approved earnings from completed lessons are visible on your Earnings dashboard and are settled according to the platform\'s settlement schedule.',	'[\"instructor\"]',	1,	0,	'published',	'2026-07-18 09:33:16',	NULL,	NULL,	'2026-07-18 09:32:58',	'2026-07-18 09:33:16',	NULL),
('019f75c0-83e9-72e7-b355-3185e56795d2',	'019f75c0-83c5-72f2-94c9-6020dae969bd',	'Can I pause bookings temporarily?',	'Yes. Vacation mode lets you pause new bookings while keeping your profile and history intact — students see that you\'re temporarily unavailable.',	'[\"instructor\"]',	2,	0,	'published',	'2026-07-18 09:33:16',	NULL,	NULL,	'2026-07-18 09:32:58',	'2026-07-18 09:33:16',	NULL),
('019f75c0-83f6-70cd-bee4-2a9965535dde',	'019f75c0-83c5-72f2-94c9-6020dae969bd',	'How is my instructor rating calculated?',	'Your rating is calculated from eligible student reviews on completed lessons and is visible on your Analytics dashboard along with quality and engagement trends.',	'[\"instructor\"]',	3,	0,	'published',	'2026-07-18 09:33:16',	NULL,	NULL,	'2026-07-18 09:32:58',	'2026-07-18 09:33:16',	NULL),
('019f75c0-8402-7301-b317-c9b94e48350e',	'019f75c0-83c5-72f2-94c9-6020dae969bd',	'How do I see which students I\'m teaching?',	'Your Students section lists everyone you have an active or past teaching relationship with, along with their recent lesson history.',	'[\"instructor\"]',	4,	0,	'published',	'2026-07-18 09:33:16',	NULL,	NULL,	'2026-07-18 09:32:58',	'2026-07-18 09:33:16',	NULL),
('019f75c0-840f-72a9-8868-d94b750b1e88',	'019f75c0-83c5-72f2-94c9-6020dae969bd',	'Do I need to accept every booking request?',	'Booking availability is based on the schedule you set — students can only book lesson slots you\'ve made available.',	'[\"instructor\"]',	5,	0,	'published',	'2026-07-18 09:33:16',	NULL,	NULL,	'2026-07-18 09:32:58',	'2026-07-18 09:33:16',	NULL);
