  CONSTRAINT `homework_assignments_booking_id_foreign` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`) ON DELETE SET NULL,
  CONSTRAINT `homework_assignments_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `homework_assignments_teacher_id_foreign` FOREIGN KEY (`teacher_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `instructor_compensation_agreements`;
CREATE TABLE `instructor_compensation_agreements` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `instructor_id` bigint unsigned NOT NULL,
  `pay_basis` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount_minor` bigint unsigned NOT NULL,
  `currency_id` bigint unsigned DEFAULT NULL,
  `currency_code` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL,
  `timezone` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `version` int unsigned NOT NULL DEFAULT '1',
  `supersedes_agreement_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `effective_from` timestamp NOT NULL,
  `effective_until` timestamp NULL DEFAULT NULL,
  `internal_reason` varchar(1000) COLLATE utf8mb4_unicode_ci NOT NULL,
  `notes` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approved_by` bigint unsigned DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `ended_by` bigint unsigned DEFAULT NULL,
  `ended_at` timestamp NULL DEFAULT NULL,
  `cancelled_by` bigint unsigned DEFAULT NULL,
  `cancelled_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint unsigned DEFAULT NULL,
  `updated_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `active_owner_key` bigint unsigned GENERATED ALWAYS AS ((case when (`status` = _utf8mb4'active') then `instructor_id` else NULL end)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `instructor_compensation_agreements_reference_unique` (`reference`),
  UNIQUE KEY `ica_active_owner_unique` (`active_owner_key`),
  KEY `instructor_compensation_agreements_currency_id_foreign` (`currency_id`),
  KEY `instructor_compensation_agreements_approved_by_foreign` (`approved_by`),
  KEY `instructor_compensation_agreements_ended_by_foreign` (`ended_by`),
  KEY `instructor_compensation_agreements_cancelled_by_foreign` (`cancelled_by`),
  KEY `instructor_compensation_agreements_created_by_foreign` (`created_by`),
  KEY `instructor_compensation_agreements_updated_by_foreign` (`updated_by`),
  KEY `ica_supersedes_foreign` (`supersedes_agreement_id`),
  KEY `ica_instructor_status_index` (`instructor_id`,`status`),
  KEY `instructor_compensation_agreements_status_index` (`status`),
  KEY `instructor_compensation_agreements_effective_from_index` (`effective_from`),
  CONSTRAINT `ica_supersedes_foreign` FOREIGN KEY (`supersedes_agreement_id`) REFERENCES `instructor_compensation_agreements` (`id`),
  CONSTRAINT `instructor_compensation_agreements_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_compensation_agreements_cancelled_by_foreign` FOREIGN KEY (`cancelled_by`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_compensation_agreements_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_compensation_agreements_currency_id_foreign` FOREIGN KEY (`currency_id`) REFERENCES `currencies` (`id`),
  CONSTRAINT `instructor_compensation_agreements_ended_by_foreign` FOREIGN KEY (`ended_by`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_compensation_agreements_instructor_id_foreign` FOREIGN KEY (`instructor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_compensation_agreements_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `instructor_compensation_exceptions`;
CREATE TABLE `instructor_compensation_exceptions` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `lesson_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `booking_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `instructor_id` bigint unsigned NOT NULL,
  `scheduled_start_at` timestamp NOT NULL,
  `category` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reason` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `retry_eligible` tinyint(1) NOT NULL DEFAULT '1',
  `attempt_count` int unsigned NOT NULL DEFAULT '1',
  `first_failed_at` timestamp NOT NULL,
  `last_attempt_at` timestamp NOT NULL,
  `next_retry_at` timestamp NULL DEFAULT NULL,
  `resolved_at` timestamp NULL DEFAULT NULL,
  `resolved_earning_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `retry_exhausted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `instructor_compensation_exceptions_lesson_id_unique` (`lesson_id`),
  KEY `instructor_compensation_exceptions_booking_id_foreign` (`booking_id`),
  KEY `instructor_compensation_exceptions_resolved_earning_id_foreign` (`resolved_earning_id`),
  KEY `ice_open_retryable_index` (`resolved_at`,`retry_eligible`),
  KEY `instructor_compensation_exceptions_category_index` (`category`),
  KEY `instructor_compensation_exceptions_instructor_id_index` (`instructor_id`),
  KEY `instructor_compensation_exceptions_next_retry_at_index` (`next_retry_at`),
  CONSTRAINT `instructor_compensation_exceptions_booking_id_foreign` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`),
  CONSTRAINT `instructor_compensation_exceptions_instructor_id_foreign` FOREIGN KEY (`instructor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_compensation_exceptions_lesson_id_foreign` FOREIGN KEY (`lesson_id`) REFERENCES `lessons` (`id`),
  CONSTRAINT `instructor_compensation_exceptions_resolved_earning_id_foreign` FOREIGN KEY (`resolved_earning_id`) REFERENCES `instructor_earnings` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `instructor_compensation_overrides`;
CREATE TABLE `instructor_compensation_overrides` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `agreement_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subject_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `academic_level_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
