  KEY `instructor_compensation_overrides_academic_level_id_foreign` (`academic_level_id`),
  KEY `instructor_compensation_overrides_subject_id_index` (`subject_id`),
  CONSTRAINT `instructor_compensation_overrides_academic_level_id_foreign` FOREIGN KEY (`academic_level_id`) REFERENCES `academic_levels` (`id`),
  CONSTRAINT `instructor_compensation_overrides_agreement_id_foreign` FOREIGN KEY (`agreement_id`) REFERENCES `instructor_compensation_agreements` (`id`),
  CONSTRAINT `instructor_compensation_overrides_subject_id_foreign` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `instructor_compensation_periods`;
CREATE TABLE `instructor_compensation_periods` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `agreement_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `instructor_id` bigint unsigned NOT NULL,
  `pay_basis` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
