  CONSTRAINT `instructor_compensation_periods_currency_id_foreign` FOREIGN KEY (`currency_id`) REFERENCES `currencies` (`id`),
  CONSTRAINT `instructor_compensation_periods_instructor_id_foreign` FOREIGN KEY (`instructor_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `instructor_document_requirements`;
CREATE TABLE `instructor_document_requirements` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
