  KEY `instructor_earnings_booking_id_foreign` (`booking_id`),
  KEY `instructor_earnings_student_id_foreign` (`student_id`),
  KEY `instructor_earnings_subject_id_foreign` (`subject_id`),
  KEY `instructor_earnings_subject_topic_id_foreign` (`subject_topic_id`),
  KEY `instructor_earnings_academic_level_id_foreign` (`academic_level_id`),
  KEY `instructor_earnings_currency_id_foreign` (`currency_id`),
  KEY `instructor_earnings_settlement_batch_id_foreign` (`settlement_batch_id`),
  KEY `instructor_earnings_created_by_foreign` (`created_by`),
  KEY `instructor_earnings_updated_by_foreign` (`updated_by`),
  KEY `instructor_earnings_instructor_id_status_index` (`instructor_id`,`status`),
  KEY `instructor_earnings_status_hold_until_index` (`status`,`hold_until`),
  KEY `instructor_earnings_currency_code_status_index` (`currency_code`,`status`),
  CONSTRAINT `instructor_earnings_academic_level_id_foreign` FOREIGN KEY (`academic_level_id`) REFERENCES `academic_levels` (`id`) ON DELETE SET NULL,
  CONSTRAINT `instructor_earnings_booking_id_foreign` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`),
  CONSTRAINT `instructor_earnings_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `instructor_earnings_currency_id_foreign` FOREIGN KEY (`currency_id`) REFERENCES `currencies` (`id`) ON DELETE SET NULL,
  CONSTRAINT `instructor_earnings_instructor_id_foreign` FOREIGN KEY (`instructor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_earnings_lesson_id_foreign` FOREIGN KEY (`lesson_id`) REFERENCES `lessons` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `instructor_earnings_settlement_batch_id_foreign` FOREIGN KEY (`settlement_batch_id`) REFERENCES `instructor_settlement_batches` (`id`) ON DELETE SET NULL,
  CONSTRAINT `instructor_earnings_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_earnings_subject_id_foreign` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE SET NULL,
  CONSTRAINT `instructor_earnings_subject_topic_id_foreign` FOREIGN KEY (`subject_topic_id`) REFERENCES `subject_topics` (`id`) ON DELETE SET NULL,
  CONSTRAINT `instructor_earnings_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `instructor_payout_attempts`;
CREATE TABLE `instructor_payout_attempts` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `withdrawal_request_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `instructor_id` bigint unsigned NOT NULL,
  `provider` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `execution_sequence` tinyint unsigned NOT NULL,
  `idempotency_key` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `request_fingerprint` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount_minor` bigint unsigned NOT NULL,
  `currency_id` bigint unsigned DEFAULT NULL,
  `currency_code` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'created',
  `provider_payout_id` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provider_status` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provider_status_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provider_response_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provider_created_at` timestamp NULL DEFAULT NULL,
  `provider_processed_at` timestamp NULL DEFAULT NULL,
  `initiated_at` timestamp NULL DEFAULT NULL,
  `acknowledged_at` timestamp NULL DEFAULT NULL,
  `processed_at` timestamp NULL DEFAULT NULL,
  `failed_at` timestamp NULL DEFAULT NULL,
  `reversed_at` timestamp NULL DEFAULT NULL,
  `last_synced_at` timestamp NULL DEFAULT NULL,
  `next_retry_at` timestamp NULL DEFAULT NULL,
  `attempt_count` smallint unsigned NOT NULL DEFAULT '0',
  `initiated_by` bigint unsigned NOT NULL,
  `failure_category` varchar(48) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `safe_failure_message` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `encrypted_provider_metadata` longtext COLLATE utf8mb4_unicode_ci,
  `requested_fake_scenario` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ipa_withdrawal_sequence_unique` (`withdrawal_request_id`,`execution_sequence`),
  UNIQUE KEY `ipa_provider_idempotency_unique` (`provider`,`idempotency_key`),
  UNIQUE KEY `instructor_payout_attempts_reference_unique` (`reference`),
  UNIQUE KEY `ipa_provider_payout_id_unique` (`provider`,`provider_payout_id`),
  KEY `instructor_payout_attempts_instructor_id_foreign` (`instructor_id`),
  KEY `instructor_payout_attempts_currency_id_foreign` (`currency_id`),
  KEY `instructor_payout_attempts_initiated_by_foreign` (`initiated_by`),
  KEY `ipa_provider_payout_id_index` (`provider`,`provider_payout_id`),
  KEY `instructor_payout_attempts_status_index` (`status`),
  KEY `instructor_payout_attempts_provider_status_index` (`provider_status`),
  KEY `instructor_payout_attempts_next_retry_at_index` (`next_retry_at`),
  KEY `instructor_payout_attempts_withdrawal_request_id_index` (`withdrawal_request_id`),
  CONSTRAINT `instructor_payout_attempts_currency_id_foreign` FOREIGN KEY (`currency_id`) REFERENCES `currencies` (`id`),
  CONSTRAINT `instructor_payout_attempts_initiated_by_foreign` FOREIGN KEY (`initiated_by`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_payout_attempts_instructor_id_foreign` FOREIGN KEY (`instructor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_payout_attempts_withdrawal_request_id_foreign` FOREIGN KEY (`withdrawal_request_id`) REFERENCES `instructor_withdrawal_requests` (`id`),
  CONSTRAINT `chk_ipa_amount_positive` CHECK ((`amount_minor` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `instructor_payout_destination_provider_links`;
CREATE TABLE `instructor_payout_destination_provider_links` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payout_method_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `instructor_id` bigint unsigned NOT NULL,
  `provider` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'razorpayx',
  `provider_contact_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provider_contact_reference` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `provider_contact_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provider_fund_account_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provider_fund_account_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bank_details_fingerprint` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `ip_allowlisting_confirmed_at` timestamp NULL DEFAULT NULL,
  `ip_allowlisting_confirmed_by` bigint unsigned DEFAULT NULL,
  `last_provisioning_attempt_at` timestamp NULL DEFAULT NULL,
  `last_provisioning_error` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provisioning_attempts` int unsigned NOT NULL DEFAULT '0',
  `disabled_at` timestamp NULL DEFAULT NULL,
  `disabled_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ipdpl_method_provider_unique` (`payout_method_id`,`provider`),
  KEY `ipdpl_ip_confirmed_by_fk` (`ip_allowlisting_confirmed_by`),
  KEY `ipdpl_disabled_by_fk` (`disabled_by`),
  KEY `ipdpl_instructor_provider_idx` (`instructor_id`,`provider`),
  KEY `ipdpl_contact_id_idx` (`provider_contact_id`),
  KEY `ipdpl_fund_account_id_idx` (`provider_fund_account_id`),
  KEY `ipdpl_status_idx` (`status`),
  CONSTRAINT `ipdpl_disabled_by_fk` FOREIGN KEY (`disabled_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ipdpl_instructor_fk` FOREIGN KEY (`instructor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `ipdpl_ip_confirmed_by_fk` FOREIGN KEY (`ip_allowlisting_confirmed_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ipdpl_payout_method_fk` FOREIGN KEY (`payout_method_id`) REFERENCES `instructor_payout_methods` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `instructor_payout_methods`;
CREATE TABLE `instructor_payout_methods` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `instructor_id` bigint unsigned NOT NULL,
  `type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'bank_transfer',
  `country_id` bigint unsigned DEFAULT NULL,
  `currency_id` bigint unsigned DEFAULT NULL,
  `currency_code` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL,
  `display_label` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `masked_identifier` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fingerprint` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `encrypted_details` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `is_default` tinyint(1) NOT NULL DEFAULT '0',
  `submitted_at` timestamp NULL DEFAULT NULL,
  `verified_at` timestamp NULL DEFAULT NULL,
  `verified_by` bigint unsigned DEFAULT NULL,
  `rejected_at` timestamp NULL DEFAULT NULL,
  `rejected_by` bigint unsigned DEFAULT NULL,
  `rejection_reason` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `disabled_at` timestamp NULL DEFAULT NULL,
  `disabled_by` bigint unsigned DEFAULT NULL,
  `last_used_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `active_default_owner_key` bigint unsigned GENERATED ALWAYS AS ((case when ((`is_default` = 1) and (`status` = _utf8mb4'verified') and (`deleted_at` is null)) then `instructor_id` else NULL end)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ipm_active_default_owner_unique` (`active_default_owner_key`),
  KEY `instructor_payout_methods_country_id_foreign` (`country_id`),
  KEY `instructor_payout_methods_currency_id_foreign` (`currency_id`),
  KEY `instructor_payout_methods_verified_by_foreign` (`verified_by`),
  KEY `instructor_payout_methods_rejected_by_foreign` (`rejected_by`),
  KEY `instructor_payout_methods_disabled_by_foreign` (`disabled_by`),
  KEY `instructor_payout_methods_instructor_id_status_index` (`instructor_id`,`status`),
  KEY `instructor_payout_methods_instructor_id_is_default_index` (`instructor_id`,`is_default`),
  KEY `instructor_payout_methods_instructor_id_fingerprint_index` (`instructor_id`,`fingerprint`),
  KEY `instructor_payout_methods_status_index` (`status`),
  KEY `instructor_payout_methods_type_index` (`type`),
  CONSTRAINT `instructor_payout_methods_country_id_foreign` FOREIGN KEY (`country_id`) REFERENCES `countries` (`id`),
  CONSTRAINT `instructor_payout_methods_currency_id_foreign` FOREIGN KEY (`currency_id`) REFERENCES `currencies` (`id`),
  CONSTRAINT `instructor_payout_methods_disabled_by_foreign` FOREIGN KEY (`disabled_by`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_payout_methods_instructor_id_foreign` FOREIGN KEY (`instructor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_payout_methods_rejected_by_foreign` FOREIGN KEY (`rejected_by`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_payout_methods_verified_by_foreign` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `instructor_payout_provider_events`;
CREATE TABLE `instructor_payout_provider_events` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `provider` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
