  UNIQUE KEY `ippe_provider_event_unique` (`provider`,`provider_event_id`),
  KEY `instructor_payout_provider_events_duplicate_of_id_foreign` (`duplicate_of_id`),
  KEY `instructor_payout_provider_events_provider_payout_id_index` (`provider_payout_id`),
  KEY `instructor_payout_provider_events_payload_hash_index` (`payload_hash`),
  KEY `instructor_payout_provider_events_processing_status_index` (`processing_status`),
  CONSTRAINT `instructor_payout_provider_events_duplicate_of_id_foreign` FOREIGN KEY (`duplicate_of_id`) REFERENCES `instructor_payout_provider_events` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `instructor_payout_reconciliation_issues`;
CREATE TABLE `instructor_payout_reconciliation_issues` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `withdrawal_request_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payout_attempt_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provider` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(48) COLLATE utf8mb4_unicode_ci NOT NULL,
  `severity` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'warning',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `local_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provider_status` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `amount_minor` bigint unsigned DEFAULT NULL,
  `currency_code` varchar(3) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `safe_summary` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `first_detected_at` timestamp NOT NULL,
  `last_detected_at` timestamp NOT NULL,
  `assigned_to` bigint unsigned DEFAULT NULL,
  `resolved_at` timestamp NULL DEFAULT NULL,
  `resolved_by` bigint unsigned DEFAULT NULL,
  `resolution_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `resolution_note` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `open_dedupe_key` varchar(150) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when (`status` = _utf8mb4'open') then concat(`withdrawal_request_id`,_utf8mb4'|',`type`) else NULL end)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `instructor_payout_reconciliation_issues_reference_unique` (`reference`),
  UNIQUE KEY `ipri_open_dedupe_unique` (`open_dedupe_key`),
  KEY `ipri_assigned_to_fk` (`assigned_to`),
  KEY `ipri_resolved_by_fk` (`resolved_by`),
  KEY `ipri_status_index` (`status`),
  KEY `ipri_severity_index` (`severity`),
  KEY `ipri_withdrawal_index` (`withdrawal_request_id`),
  KEY `ipri_attempt_index` (`payout_attempt_id`),
  CONSTRAINT `ipri_assigned_to_fk` FOREIGN KEY (`assigned_to`) REFERENCES `users` (`id`),
  CONSTRAINT `ipri_attempt_fk` FOREIGN KEY (`payout_attempt_id`) REFERENCES `instructor_payout_attempts` (`id`),
  CONSTRAINT `ipri_resolved_by_fk` FOREIGN KEY (`resolved_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ipri_withdrawal_fk` FOREIGN KEY (`withdrawal_request_id`) REFERENCES `instructor_withdrawal_requests` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


