  CONSTRAINT `instructor_subject_topics_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `instructor_subject_topics_subject_id_foreign` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `instructor_subject_topics_subject_topic_id_foreign` FOREIGN KEY (`subject_topic_id`) REFERENCES `subject_topics` (`id`) ON DELETE CASCADE,
  CONSTRAINT `instructor_subject_topics_teacher_id_foreign` FOREIGN KEY (`teacher_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `instructor_withdrawal_allocations`;
CREATE TABLE `instructor_withdrawal_allocations` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `withdrawal_request_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `instructor_earning_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `currency_id` bigint unsigned DEFAULT NULL,
  `currency_code` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount_minor` bigint unsigned NOT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'reserved',
  `reserved_at` timestamp NOT NULL,
  `released_at` timestamp NULL DEFAULT NULL,
  `consumed_at` timestamp NULL DEFAULT NULL,
  `reversed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `iwa_request_earning_unique` (`withdrawal_request_id`,`instructor_earning_id`),
  KEY `instructor_withdrawal_allocations_currency_id_foreign` (`currency_id`),
  KEY `iwa_earning_status_index` (`instructor_earning_id`,`status`),
  KEY `instructor_withdrawal_allocations_status_index` (`status`),
  CONSTRAINT `instructor_withdrawal_allocations_currency_id_foreign` FOREIGN KEY (`currency_id`) REFERENCES `currencies` (`id`),
  CONSTRAINT `instructor_withdrawal_allocations_instructor_earning_id_foreign` FOREIGN KEY (`instructor_earning_id`) REFERENCES `instructor_earnings` (`id`),
  CONSTRAINT `instructor_withdrawal_allocations_withdrawal_request_id_foreign` FOREIGN KEY (`withdrawal_request_id`) REFERENCES `instructor_withdrawal_requests` (`id`),
  CONSTRAINT `chk_iwa_amount_positive` CHECK ((`amount_minor` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `instructor_withdrawal_requests`;
CREATE TABLE `instructor_withdrawal_requests` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `instructor_id` bigint unsigned NOT NULL,
  `payout_method_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `currency_id` bigint unsigned DEFAULT NULL,
  `currency_code` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount_minor` bigint unsigned NOT NULL,
  `fee_minor` bigint unsigned NOT NULL DEFAULT '0',
  `net_amount_minor` bigint unsigned NOT NULL,
  `available_balance_before_minor` bigint unsigned NOT NULL,
  `available_balance_after_minor` bigint unsigned NOT NULL,
  `payout_method_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payout_method_label` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `masked_identifier` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `encrypted_payout_method_snapshot` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'submitted',
  `idempotency_key` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `instructor_note` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `internal_review_note` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rejection_reason` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `requested_at` timestamp NOT NULL,
  `review_started_at` timestamp NULL DEFAULT NULL,
  `review_started_by` bigint unsigned DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `approved_by` bigint unsigned DEFAULT NULL,
  `rejected_at` timestamp NULL DEFAULT NULL,
  `rejected_by` bigint unsigned DEFAULT NULL,
  `cancelled_at` timestamp NULL DEFAULT NULL,
  `cancelled_by` bigint unsigned DEFAULT NULL,
  `processing_at` timestamp NULL DEFAULT NULL,
  `paid_at` timestamp NULL DEFAULT NULL,
  `failed_at` timestamp NULL DEFAULT NULL,
  `reversed_at` timestamp NULL DEFAULT NULL,
  `reversed_by` bigint unsigned DEFAULT NULL,
  `failure_reason` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recovered_at` timestamp NULL DEFAULT NULL,
  `recovered_by` bigint unsigned DEFAULT NULL,
  `recovery_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `instructor_withdrawal_requests_reference_unique` (`reference`),
  UNIQUE KEY `iwr_instructor_idempotency_unique` (`instructor_id`,`idempotency_key`),
  KEY `instructor_withdrawal_requests_currency_id_foreign` (`currency_id`),
  KEY `instructor_withdrawal_requests_review_started_by_foreign` (`review_started_by`),
  KEY `instructor_withdrawal_requests_approved_by_foreign` (`approved_by`),
  KEY `instructor_withdrawal_requests_rejected_by_foreign` (`rejected_by`),
  KEY `instructor_withdrawal_requests_cancelled_by_foreign` (`cancelled_by`),
  KEY `iwr_instructor_status_index` (`instructor_id`,`status`),
  KEY `iwr_currency_status_index` (`currency_code`,`status`),
  KEY `instructor_withdrawal_requests_status_index` (`status`),
  KEY `instructor_withdrawal_requests_requested_at_index` (`requested_at`),
  KEY `instructor_withdrawal_requests_payout_method_id_index` (`payout_method_id`),
  KEY `instructor_withdrawal_requests_reversed_by_foreign` (`reversed_by`),
  KEY `instructor_withdrawal_requests_recovered_by_foreign` (`recovered_by`),
  CONSTRAINT `instructor_withdrawal_requests_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_withdrawal_requests_cancelled_by_foreign` FOREIGN KEY (`cancelled_by`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_withdrawal_requests_currency_id_foreign` FOREIGN KEY (`currency_id`) REFERENCES `currencies` (`id`),
  CONSTRAINT `instructor_withdrawal_requests_instructor_id_foreign` FOREIGN KEY (`instructor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_withdrawal_requests_payout_method_id_foreign` FOREIGN KEY (`payout_method_id`) REFERENCES `instructor_payout_methods` (`id`),
  CONSTRAINT `instructor_withdrawal_requests_recovered_by_foreign` FOREIGN KEY (`recovered_by`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_withdrawal_requests_rejected_by_foreign` FOREIGN KEY (`rejected_by`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_withdrawal_requests_reversed_by_foreign` FOREIGN KEY (`reversed_by`) REFERENCES `users` (`id`),
  CONSTRAINT `instructor_withdrawal_requests_review_started_by_foreign` FOREIGN KEY (`review_started_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `job_batches`;
CREATE TABLE `job_batches` (
  `id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
