  CONSTRAINT `lessons_attendance_record_id_foreign` FOREIGN KEY (`attendance_record_id`) REFERENCES `lesson_attendance_records` (`id`) ON DELETE SET NULL,
  CONSTRAINT `lessons_booking_id_foreign` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `lessons_completed_by_foreign` FOREIGN KEY (`completed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `lessons_instructor_id_foreign` FOREIGN KEY (`instructor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `lessons_outcome_finalized_by_foreign` FOREIGN KEY (`outcome_finalized_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `lessons_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `users` (`id`),
