  KEY `quality_alerts_instructor_id_status_index` (`instructor_id`,`status`),
  KEY `quality_alerts_alert_type_status_index` (`alert_type`,`status`),
  KEY `quality_alerts_source_type_source_id_index` (`source_type`,`source_id`),
  CONSTRAINT `quality_alerts_assigned_to_foreign` FOREIGN KEY (`assigned_to`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `quality_alerts_instructor_id_foreign` FOREIGN KEY (`instructor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `quality_alerts_reviewed_by_foreign` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `referral_attributions`;
CREATE TABLE `referral_attributions` (
