  CONSTRAINT `referral_attributions_referred_student_id_foreign` FOREIGN KEY (`referred_student_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `referral_attributions_referrer_id_foreign` FOREIGN KEY (`referrer_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
