  `ends_at` timestamp NOT NULL,
  `reward_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reward_value` int unsigned NOT NULL,
  `reward_currency_id` bigint unsigned DEFAULT NULL,
  `reward_currency_code` varchar(3) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `min_completed_paid_lessons` smallint unsigned NOT NULL DEFAULT '1',
  `max_rewarded_classes` smallint unsigned NOT NULL DEFAULT '10',
  `reward_timing` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'immediate',
  `hold_days` smallint unsigned NOT NULL DEFAULT '0',
  `requires_fraud_review` tinyint(1) NOT NULL DEFAULT '0',
  `terms` text COLLATE utf8mb4_unicode_ci,
  `created_by` bigint unsigned DEFAULT NULL,
  `updated_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `referral_campaigns_reward_currency_id_foreign` (`reward_currency_id`),
  KEY `referral_campaigns_created_by_foreign` (`created_by`),
  KEY `referral_campaigns_updated_by_foreign` (`updated_by`),
  KEY `referral_campaigns_status_starts_at_ends_at_index` (`status`,`starts_at`,`ends_at`),
  CONSTRAINT `referral_campaigns_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `referral_campaigns_reward_currency_id_foreign` FOREIGN KEY (`reward_currency_id`) REFERENCES `currencies` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `referral_campaigns_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_referral_campaigns_currency_pairing` CHECK ((((`reward_type` = _utf8mb4'fixed') and (`reward_currency_code` is not null)) or ((`reward_type` <> _utf8mb4'fixed') and (`reward_currency_code` is null)))),
  CONSTRAINT `chk_referral_campaigns_hold_pairing` CHECK ((((`reward_timing` = _utf8mb4'immediate') and (`hold_days` = 0)) or ((`reward_timing` <> _utf8mb4'immediate') and (`hold_days` >= 1)))),
  CONSTRAINT `chk_referral_campaigns_max_classes` CHECK ((`max_rewarded_classes` >= 1)),
  CONSTRAINT `chk_referral_campaigns_min_lessons` CHECK ((`min_completed_paid_lessons` >= 1)),
  CONSTRAINT `chk_referral_campaigns_percentage_max` CHECK (((`reward_type` <> _utf8mb4'percentage') or (`reward_value` <= 10000))),
  CONSTRAINT `chk_referral_campaigns_reward_positive` CHECK ((`reward_value` > 0)),
  CONSTRAINT `chk_referral_campaigns_time_range` CHECK ((`starts_at` < `ends_at`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `referral_codes`;
CREATE TABLE `referral_codes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `disabled_at` timestamp NULL DEFAULT NULL,
  `disabled_by` bigint unsigned DEFAULT NULL,
  `disable_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `referral_codes_user_id_unique` (`user_id`),
  UNIQUE KEY `referral_codes_code_unique` (`code`),
  KEY `referral_codes_disabled_by_foreign` (`disabled_by`),
  CONSTRAINT `referral_codes_disabled_by_foreign` FOREIGN KEY (`disabled_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `referral_codes_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `referral_rewards`;
CREATE TABLE `referral_rewards` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `attribution_id` bigint unsigned NOT NULL,
  `campaign_id` bigint unsigned NOT NULL,
  `referrer_id` bigint unsigned NOT NULL,
  `referred_student_id` bigint unsigned NOT NULL,
  `lesson_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `booking_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `class_sequence` smallint unsigned NOT NULL,
  `lesson_amount_minor` int unsigned NOT NULL,
  `lesson_currency_code` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reward_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reward_value` int unsigned NOT NULL,
  `reward_amount_minor` int unsigned NOT NULL,
  `reward_currency_code` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'eligible',
  `hold_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `decision_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `decided_by` bigint unsigned DEFAULT NULL,
  `eligible_at` timestamp NOT NULL,
  `credit_ready_at` timestamp NULL DEFAULT NULL,
  `credited_at` timestamp NULL DEFAULT NULL,
  `rejected_at` timestamp NULL DEFAULT NULL,
  `reversed_at` timestamp NULL DEFAULT NULL,
  `wallet_ledger_entry_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reversal_ledger_entry_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `referral_rewards_attribution_sequence_unique` (`attribution_id`,`class_sequence`),
  UNIQUE KEY `referral_rewards_lesson_id_unique` (`lesson_id`),
  KEY `referral_rewards_campaign_id_foreign` (`campaign_id`),
  KEY `referral_rewards_referred_student_id_foreign` (`referred_student_id`),
  KEY `referral_rewards_decided_by_foreign` (`decided_by`),
  KEY `referral_rewards_booking_id_foreign` (`booking_id`),
  KEY `referral_rewards_wallet_ledger_entry_id_foreign` (`wallet_ledger_entry_id`),
  KEY `referral_rewards_reversal_ledger_entry_id_foreign` (`reversal_ledger_entry_id`),
  KEY `referral_rewards_status_credit_ready_at_index` (`status`,`credit_ready_at`),
  KEY `referral_rewards_referrer_id_status_index` (`referrer_id`,`status`),
  CONSTRAINT `referral_rewards_attribution_id_foreign` FOREIGN KEY (`attribution_id`) REFERENCES `referral_attributions` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `referral_rewards_booking_id_foreign` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `referral_rewards_campaign_id_foreign` FOREIGN KEY (`campaign_id`) REFERENCES `referral_campaigns` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `referral_rewards_decided_by_foreign` FOREIGN KEY (`decided_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `referral_rewards_lesson_id_foreign` FOREIGN KEY (`lesson_id`) REFERENCES `lessons` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `referral_rewards_referred_student_id_foreign` FOREIGN KEY (`referred_student_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `referral_rewards_referrer_id_foreign` FOREIGN KEY (`referrer_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `referral_rewards_reversal_ledger_entry_id_foreign` FOREIGN KEY (`reversal_ledger_entry_id`) REFERENCES `wallet_ledger_entries` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `referral_rewards_wallet_ledger_entry_id_foreign` FOREIGN KEY (`wallet_ledger_entry_id`) REFERENCES `wallet_ledger_entries` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `chk_referral_rewards_credited_ledger` CHECK (((`status` <> _utf8mb4'credited') or (`wallet_ledger_entry_id` is not null))),
  CONSTRAINT `chk_referral_rewards_no_self` CHECK ((`referrer_id` <> `referred_student_id`)),
  CONSTRAINT `chk_referral_rewards_reversed_ledger` CHECK (((`status` <> _utf8mb4'reversed') or ((`wallet_ledger_entry_id` is not null) and (`reversal_ledger_entry_id` is not null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `review_rating_contributions`;
CREATE TABLE `review_rating_contributions` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `review_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `instructor_id` bigint unsigned NOT NULL,
  `included` tinyint(1) NOT NULL DEFAULT '0',
  `overall_rating` tinyint unsigned DEFAULT NULL,
  `teaching_quality_rating` tinyint unsigned DEFAULT NULL,
  `communication_rating` tinyint unsigned DEFAULT NULL,
  `punctuality_rating` tinyint unsigned DEFAULT NULL,
  `preparedness_rating` tinyint unsigned DEFAULT NULL,
  `learning_value_rating` tinyint unsigned DEFAULT NULL,
  `lesson_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `applied_review_version` int unsigned DEFAULT NULL,
  `applied_at` timestamp NULL DEFAULT NULL,
  `removed_at` timestamp NULL DEFAULT NULL,
  `version` int unsigned NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `review_rating_contributions_review_id_unique` (`review_id`),
  KEY `review_rating_contributions_instructor_id_included_index` (`instructor_id`,`included`),
  CONSTRAINT `review_rating_contributions_instructor_id_foreign` FOREIGN KEY (`instructor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `review_rating_contributions_review_id_foreign` FOREIGN KEY (`review_id`) REFERENCES `lesson_reviews` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `review_reports`;
CREATE TABLE `review_reports` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `review_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reporter_id` bigint unsigned NOT NULL,
  `reason` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `explanation` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `submitted_at` timestamp NOT NULL,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  `reviewed_by` bigint unsigned DEFAULT NULL,
  `resolution_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `resolution_action` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int unsigned NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `review_reports_reviewed_by_foreign` (`reviewed_by`),
  KEY `review_reports_review_id_status_index` (`review_id`,`status`),
  KEY `review_reports_reporter_id_index` (`reporter_id`),
  CONSTRAINT `review_reports_reporter_id_foreign` FOREIGN KEY (`reporter_id`) REFERENCES `users` (`id`),
  CONSTRAINT `review_reports_review_id_foreign` FOREIGN KEY (`review_id`) REFERENCES `lesson_reviews` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `review_reports_reviewed_by_foreign` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `review_tags`;
CREATE TABLE `review_tags` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
