DROP TABLE IF EXISTS `scheduler_histories`;
CREATE TABLE `scheduler_histories` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `command` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
