  KEY `student_favorite_instructors_instructor_user_id_foreign` (`instructor_user_id`),
  CONSTRAINT `student_favorite_instructors_instructor_user_id_foreign` FOREIGN KEY (`instructor_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `student_favorite_instructors_student_user_id_foreign` FOREIGN KEY (`student_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `student_learning_goals`;
CREATE TABLE `student_learning_goals` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `subject_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `academic_level_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `target_date` date DEFAULT NULL,
  `priority` tinyint unsigned DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `completed_at` timestamp NULL DEFAULT NULL,
  `archived_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint unsigned DEFAULT NULL,
  `updated_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `student_learning_goals_created_by_foreign` (`created_by`),
  KEY `student_learning_goals_updated_by_foreign` (`updated_by`),
  KEY `student_learning_goals_academic_level_id_foreign` (`academic_level_id`),
  KEY `student_learning_goals_user_id_status_index` (`user_id`,`status`),
  KEY `student_learning_goals_subject_id_status_index` (`subject_id`,`status`),
  CONSTRAINT `student_learning_goals_academic_level_id_foreign` FOREIGN KEY (`academic_level_id`) REFERENCES `academic_levels` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_learning_goals_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_learning_goals_subject_id_foreign` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `student_learning_goals_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_learning_goals_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `student_learning_plans`;
CREATE TABLE `student_learning_plans` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `student_user_id` bigint unsigned NOT NULL,
  `learning_goal_id` bigint unsigned NOT NULL,
  `primary_instructor_user_id` bigint unsigned DEFAULT NULL,
  `subject_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `academic_level_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` text COLLATE utf8mb4_unicode_ci,
  `initial_assessment` text COLLATE utf8mb4_unicode_ci,
  `recommended_frequency` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recommended_lesson_duration_minutes` smallint unsigned DEFAULT NULL,
  `preferred_schedule_note` text COLLATE utf8mb4_unicode_ci,
  `current_focus` text COLLATE utf8mb4_unicode_ci,
  `current_level_note` text COLLATE utf8mb4_unicode_ci,
  `target_completion_date` date DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `progress_percent` tinyint unsigned DEFAULT NULL,
  `started_at` timestamp NULL DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `archived_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint unsigned DEFAULT NULL,
  `updated_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `student_learning_plans_created_by_foreign` (`created_by`),
  KEY `student_learning_plans_updated_by_foreign` (`updated_by`),
  KEY `student_learning_plans_subject_id_foreign` (`subject_id`),
  KEY `student_learning_plans_academic_level_id_foreign` (`academic_level_id`),
  KEY `student_learning_plans_student_user_id_status_index` (`student_user_id`,`status`),
  KEY `learning_plans_instructor_status_index` (`primary_instructor_user_id`,`status`),
  KEY `student_learning_plans_learning_goal_id_status_index` (`learning_goal_id`,`status`),
  CONSTRAINT `student_learning_plans_academic_level_id_foreign` FOREIGN KEY (`academic_level_id`) REFERENCES `academic_levels` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_learning_plans_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_learning_plans_learning_goal_id_foreign` FOREIGN KEY (`learning_goal_id`) REFERENCES `student_learning_goals` (`id`) ON DELETE CASCADE,
  CONSTRAINT `student_learning_plans_primary_instructor_user_id_foreign` FOREIGN KEY (`primary_instructor_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_learning_plans_student_user_id_foreign` FOREIGN KEY (`student_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
