  CONSTRAINT `student_lesson_prices_academic_level_id_foreign` FOREIGN KEY (`academic_level_id`) REFERENCES `academic_levels` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `student_lesson_prices_booking_type_id_foreign` FOREIGN KEY (`booking_type_id`) REFERENCES `booking_types` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `student_lesson_prices_country_id_foreign` FOREIGN KEY (`country_id`) REFERENCES `countries` (`id`) ON DELETE RESTRICT,
